import subprocess, re, os, glob, collections

REPO = "/tmp/shurik-workspace-9Zjpz8"
BRANCHES = ["ross", "monica", "rachel", "phoebe", "joey", "chandler"]

def git(*args):
    return subprocess.check_output(["git", "-C", REPO] + list(args), text=True, errors="replace")

entries = {}  # sha -> dict
for b in BRANCHES:
    log = git("log", "--format=%H%x1f%cI%x1f%s", f"origin/friend/{b}")
    for line in log.splitlines():
        if not line.strip():
            continue
        sha, date, subject = line.split("\x1f")
        body = git("show", "-s", "--format=%B", sha)
        if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
            continue
        m = re.search(r"^Speaker: (.*)$", body, re.M)
        e = re.search(r"^Episode: (\S+)\s*$", body, re.M)
        r = re.search(r"^Reply-To: (\S+)\s*$", body, re.M)
        if not (m and e):
            continue
        # text after blank line following Reply-To
        idx = body.find("Reply-To:")
        rest = body[idx:]
        parts = rest.split("\n\n", 1)
        text = parts[1] if len(parts) > 1 else ""
        text = text.rstrip("\n")
        entries[sha] = dict(branch=b, sha=sha, date=date, speaker=m.group(1).strip(),
                            episode=e.group(1), reply_to=(r.group(1).strip() if r else "none"), text=text)

print("total message commits:", len(entries))
byep = collections.Counter(v["episode"] for v in entries.values())
for ep, n in sorted(byep.items()):
    print(ep, n)

# filed shas
filed = set()
files = {}
for path in glob.glob("/tmp/ross-main/S0*/E*.md"):
    txt = open(path).read()
    shas = set(re.findall(r"Source: friend/(\w+) @ ([0-9a-f]{40})", txt))
    files[path] = shas
    for br, s in shas:
        filed.add(s)

missing = collections.defaultdict(list)
for sha, v in entries.items():
    if sha not in filed:
        missing[v["episode"]].append(v)

print("\n=== MISSING ===")
for ep in sorted(missing):
    print(ep, len(missing[ep]))
    for v in sorted(missing[ep], key=lambda x: (x["date"], x["sha"])):
        print("  ", v["date"], v["branch"], v["sha"][:10], "reply_to=" + v["reply_to"][:10], repr(v["text"][:70]))

# also: filed shas that are not in entries (unknown)
print("\n=== FILED BUT NOT FOUND IN BRANCHES ===")
for path, shas in files.items():
    for br, s in shas:
        if s not in entries:
            print(path, br, s)

import subprocess, re, glob, os, sys

REPO = "/tmp/shurik-workspace-9Zjpz8"
BRANCHES = ["ross", "monica", "rachel", "phoebe", "joey", "chandler"]

def git(*args):
    return subprocess.check_output(["git", "-C", REPO] + list(args), text=True, errors="replace")

def collect(ep):
    out = []
    for b in BRANCHES:
        for sha in git("log", "--format=%H", f"origin/friend/{b}").split():
            body = git("show", "-s", "--format=%B", sha)
            if not re.search(r"^Episode: %s\s*$" % re.escape(ep), body, re.M):
                continue
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            speaker = re.search(r"^Speaker: (.*)$", body, re.M).group(1).strip()
            i = body.find("Reply-To:")
            rest = body[i:]
            text = rest.split("\n\n", 1)[1].rstrip("\n") if "\n\n" in rest else ""
            date = git("show", "-s", "--format=%cI", sha).strip()
            ts = git("show", "-s", "--format=%cI", sha).strip()
            # scene time from stage direction like (Monday, two oh five, ...)
            m = re.match(r"^[A-Za-z]+: \(.*?,\s*([a-z][a-z ]*?)(?:,|\))", text)
            scene = m.group(1).strip() if m else ""
            out.append(dict(sha=sha, branch=b, speaker=speaker, date=date, ts=ts, scene=scene, text=text))
    return out

def order(entries):
    # primary: commit time; ties: scene-time word ordering (natural English order of spoken clock times)
    def clockkey(scene):
        if not scene:
            return (99, 0)
        words = scene.replace("oh", "o").split()
        # forms: "one oh twenty" -> 1:20 ; "noon" ; "three o'clock"
        num = {"noon": 12, "midnight": 0}
        # find hour word
        hour = None
        minute = 0
        parts = scene.split()
        # join words
        s = " ".join(parts).replace("o'clock", "oclock").replace("oh", "o")
        m = re.match(r"^(?:(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)[,\s]+)?(.+)$", s)
        rest = m.group(1).strip() if m else s
        hm = re.match(r"^([a-z]+)(?:\s+o\s*)?(?:\s+([a-z]+))?$", rest)
        if not hm:
            return (99, 0)
        h = hm.group(1)
        mins = hm.group(2)
        hour = num.get(h)
        if hour is None:
            mapping = {"one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,
                       "nine":9,"ten":10,"eleven":11,"twelve":12,"twelve":12,"thirteen":13}
            hour = mapping.get(h)
        if hour is None:
            return (99, 0)
        if mins:
            mm = {"oh":0}
            digits = {"ten":10,"fifteen":15,"twenty":20,"twentyfive":25,"thirty":30,"thirtyfive":35,
                      "forty":40,"fortyfive":45,"fifty":50,"fiftyfive":55}
            m2 = re.match(r"^o\s*([a-z]+)$", mins.replace(" ",""))
            key = mins.replace(" ","")
            if key in digits:
                minute = digits[key]
            elif m2:
                minute = digits.get(m2.group(1), 0)
            else:
                minute = 0
        return (hour, minute)
    return sorted(entries, key=lambda e: (e["date"], clockkey(e["scene"]), e["sha"]))

def render(entries):
    parts = []
    for e in entries:
        parts.append("**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s" % (e["speaker"], e["ts"], e["branch"], e["sha"], e["text"]))
    return "\n\n".join(parts) + "\n"

if __name__ == "__main__":
    ep = sys.argv[1]
    path = "/tmp/ross-main/%s.md" % ep
    cur = open(path).read()
    entries = collect(ep)
    entries = order(entries)
    body = re.split(r"\n---\n", cur, 2)[2]  # after frontmatter
    # body starts with "\n" then summary paragraph then entries
    m = re.match(r"\n\n(.*?)\n\n(?=\*\*)", body, re.S)
    if not m:
        print("could not parse summary paragraph", file=sys.stderr)
        sys.exit(1)
    summary_para = m.group(1)
    old_entries = body[m.end():]
    new_body = "\n\n" + summary_para + "\n\n" + render(entries)
    out = cur[:cur.index("\n---\n", 5)] + "\n---\n" + new_body
    # preserve exact frontmatter (before second ---)
    print(out[:400])
    open("/tmp/new_%s.md" % ep.replace("/", "_"), "w").write(out)
    # diff report
    old_shas = re.findall(r"Source: friend/\w+ @ ([0-9a-f]{40})", old_entries)
    new_shas = re.findall(r"Source: friend/\w+ @ ([0-9a-f]{40})", new_body)
    print("old count", len(old_shas), "new count", len(new_shas))
    print("added:", [s[:10] for s in new_shas if s not in old_shas])
    print("removed:", [s[:10] for s in old_shas if s not in new_shas])
    # check published entries unchanged textually
    old_by_sha = {}
    for m2 in re.finditer(r"\*\*(\w+)\*\* \(([^)]+)\)\n\nSource: friend/\w+ @ ([0-9a-f]{40})\n\n(.*?)(?=\n\n\*\*|\Z)", old_entries, re.S):
        old_by_sha[m2.group(3)] = m2.group(4)
    new_by_sha = {}
    for m2 in re.finditer(r"\*\*(\w+)\*\* \(([^)]+)\)\n\nSource: friend/\w+ @ ([0-9a-f]{40})\n\n(.*?)(?=\n\n\*\*|\Z)", new_body, re.S):
        new_by_sha[m2.group(3)] = m2.group(4)
    bad = [s for s in old_by_sha if s in new_by_sha and old_by_sha[s] != new_by_sha[s]]
    print("text changed for:", bad)

import subprocess, re, sys, os

REPO = "/tmp/shurik-workspace-9Zjpz8"
BRANCHES = ["ross", "monica", "rachel", "phoebe", "joey", "chandler"]

def git(*args):
    return subprocess.check_output(["git", "-C", REPO] + list(args), text=True, errors="replace")

def clockkey(scene):
    if not scene:
        return (99, 0)
    s = " ".join(scene.replace("o'clock", "oclock").split()).replace("oh", "o")
    hm = re.match(r"^([a-z]+)(?:\s+o)?(?:\s+([a-z]+))?$", s)
    if not hm:
        return (99, 0)
    hours = {"noon": 12, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6,
             "seven": 7, "eight": 8, "nine": 9, "ten": 10, "eleven": 11, "twelve": 12}
    h = hours.get(hm.group(1))
    if h is None:
        return (99, 0)
    mins = 0
    if hm.group(2):
        digits = {"ten": 10, "fifteen": 15, "twenty": 20, "twentyfive": 25, "thirty": 30,
                  "thirtyfive": 35, "forty": 40, "fortyfive": 45, "fifty": 50, "fiftyfive": 55}
        key = hm.group(2).replace(" ", "")
        mins = digits.get(key, 0)
    return (h, mins)

def scene_of(text):
    m = re.match(r"^[A-Za-z]+: \((.*?),\s*([a-z][a-z ]*?)(?:,|\))", text)
    return m.group(2).strip() if m else ""

def collect(ep):
    out = []
    for b in BRANCHES:
        for sha in git("log", "--format=%H", f"origin/friend/{b}").split():
            body = git("show", "-s", "--format=%B", sha)
            if not re.search(r"^Episode: %s\s*$" % re.escape(ep), body, re.M):
                continue
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            speaker = re.search(r"^Speaker: (.*)$", body, re.M).group(1).strip()
            i = body.find("Reply-To:")
            rest = body[i:]
            text = rest.split("\n\n", 1)[1].rstrip("\n") if "\n\n" in rest else ""
            ts = git("show", "-s", "--format=%cI", sha).strip()
            out.append(dict(sha=sha, branch=b, speaker=speaker, ts=ts, date=ts,
                            scene=scene_of(text), text=text))
    return out

BLOCK_RE = re.compile(r"(?=\*\*[A-Za-z ]+\*\* \(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ\))")

def split_blocks(body):
    parts = [p for p in BLOCK_RE.split(body) if p.strip()]
    return parts

def sha_of(block):
    m = re.search(r"Source: friend/\w+ @ ([0-9a-f]{40})", block)
    return m.group(1) if m else None

def main(ep, path):
    cur = open(path).read()
    fi = cur.index("\n---\n", 4)
    head = cur[:fi] + "\n---\n"
    body = cur[fi + 5:]
    m = re.match(r"\s*(.*?)\n\n(?=\*\*)", body, re.S)
    summary = m.group(1)
    blocks = split_blocks(body)
    blocks = [b.rstrip("\n") for b in blocks]
    existing = {sha_of(b): b for b in blocks if sha_of(b)}
    entries = collect(ep)
    new = [e for e in entries if e["sha"] not in existing]
    # key for existing blocks: need commit date -> look up from entries map
    emap = {e["sha"]: e for e in entries}
    def key_for(sha, block):
        if sha in emap:
            e = emap[sha]
            return (e["date"], clockkey(e["scene"]), sha)
        m = re.search(r"\*\*[A-Za-z ]+\*\* \((\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)\)", block)
        return (m.group(1) if m else "", (99, 0), sha)
    merged = [(key_for(sha_of(b), b), b) for b in blocks if sha_of(b)]
    for e in new:
        block = "**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s" % (e["speaker"], e["ts"], e["branch"], e["sha"], e["text"])
        merged.append(((e["date"], clockkey(e["scene"]), e["sha"]), block))
    merged.sort(key=lambda x: x[0])
    out = head + "\n" + summary + "\n\n" + "\n\n".join(b for _, b in merged) + "\n"
    outp = "/tmp/out_%s.md" % ep.replace("/", "_")
    open(outp, "w").write(out)
    old_shas = [sha_of(b) for b in blocks if sha_of(b)]
    new_shas = [sha_of(b) for _, b in merged]
    print("episode", ep, "old", len(old_shas), "new", len(new_shas))
    print("added:", [s[:10] for s in new_shas if s not in old_shas])
    print("removed:", [s[:10] for s in old_shas if s not in new_shas])
    # verify existing block bytes preserved
    changed = [s for s in old_shas if existing[s] != dict(merged)[s]]
    print("existing blocks modified:", changed)
    # order check
    print("order ok:", old_shas == [s for s in new_shas if s in old_shas])

if __name__ == "__main__":
    ep = sys.argv[1]
    main(ep, "/tmp/ross-main/%s.md" % ep)

