import subprocess, re, collections, json

REPO = "/tmp/shurik-workspace-9Zjpz8"
BRANCHES = ["ross", "monica", "rachel", "phoebe", "joey", "chandler"]

def git(*args):
    return subprocess.check_output(["git", "-C", REPO] + list(args), text=True, errors="replace")

def collect(ep):
    out = []
    for b in BRANCHES:
        for sha in git("log", "--format=%H", f"origin/friend/{b}").split():
            body = git("show", "-s", "--format=%B", sha)
            if not re.search(r"^Episode: %s\s*$" % re.escape(ep), body, re.M):
                continue
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            speaker = re.search(r"^Speaker: (.*)$", body, re.M).group(1).strip()
            r = re.search(r"^Reply-To: (\S+)\s*$", body, re.M)
            reply = r.group(1).strip() if r else "none"
            i = body.find("Reply-To:")
            rest = body[i:] if i >= 0 else body
            text = rest.split("\n\n", 1)[1].rstrip("\n") if "\n\n" in rest else ""
            ts = git("show", "-s", "--format=%cI", sha).strip()
            extra = [l for l in body.splitlines()
                     if l.startswith(("Correction-Request:", "Late-Arrival:", "Episode-Note:", "Note:"))]
            out.append(dict(sha=sha, branch=b, speaker=speaker, ts=ts, date=ts, reply=reply,
                            text=text, extra=extra))
    return out

if __name__ == "__main__":
    import sys
    ep = sys.argv[1]
    ents = collect(ep)
    ents.sort(key=lambda e: (e["date"], e["sha"]))
    print("total", len(ents))
    # duplicate text detection
    bytext = collections.defaultdict(list)
    for e in ents:
        bytext[e["text"]].append(e)
    for t, lst in bytext.items():
        if len(lst) > 1:
            print("DUPLICATE TEXT x%d:" % len(lst))
            for e in lst:
                print("   ", e["date"], e["branch"], e["sha"], "reply=" + e["reply"][:10])
            print("    text:", repr(t[:100]))
    # reply-to pointing at unknown sha
    known = {e["sha"] for e in ents}
    print("\nunknown reply-to:")
    for e in ents:
        if e["reply"] != "none" and e["reply"] not in known:
            # check existence in repo
            try:
                git("cat-file", "-e", e["reply"] + "^{commit}")
                exists = True
            except subprocess.CalledProcessError:
                exists = False
            print("  ", e["branch"], e["sha"][:10], "reply=", e["reply"][:12], "exists=", exists)
    print("\nwith extra headers:")
    for e in ents:
        if e["extra"]:
            print("  ", e["branch"], e["sha"][:10], e["extra"][0][:110])
